(() => {
  if (window.__BB_CLIENT_HUB_V204__) return;
  window.__BB_CLIENT_HUB_V126__ = true;
  const q = s => document.querySelector(s);
  const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fmtTime = seconds => { const sec=Math.max(0,Math.round(Number(seconds)||0)); const d=Math.floor(sec/86400),h=Math.floor(sec%86400/3600),m=Math.floor(sec%3600/60); if(d)return `${d}d ${h}h`; if(h)return `${h}h ${m}m`; return `${m}m`; };
  const fmtClock = seconds => { const sec=Math.max(0,Math.floor(Number(seconds)||0)); const h=Math.floor(sec/3600),m=Math.floor(sec%3600/60),s=sec%60; return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`; };
  const localDay = v => { const d=new Date(v); if(Number.isNaN(d.getTime()))return ''; return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; };
  const profileLabel=(typeof profileName!=='undefined'&&profileName)?String(profileName):'BoomBang';
  const standalone = () => window.__BB_HUB_STANDALONE__ === true;
  const closeHub = () => standalone() ? ipcRenderer.invoke('hub:close-window', profileId) : toggle(false);
  let data=null,open=false,tab='home',root=null,content=null,tabs=null,refreshTimer=null,currentGame={id:'unknown',label:'No detectado',confidence:0};
  const currentSessionSeconds=()=>Math.max(0,Math.round((Date.now()-(Number(typeof sessionStartedAt!=='undefined'?sessionStartedAt:Date.now())))/1000));
  const todayPlayedSeconds=()=>{const day=localDay(Date.now());const past=(data?.history||[]).filter(h=>localDay(h.startedAt)===day).reduce((n,h)=>n+(Number(h.seconds)||0),0);return past+currentSessionSeconds();};
  const heapText=()=>{try{return performance.memory?.usedJSHeapSize?`${Math.round(performance.memory.usedJSHeapSize/1048576)} MB`:'—';}catch(_){return '—';}};
  const pingText=()=>{const v=typeof statusMessage!=='undefined'?statusMessage.latency:null;return Number.isFinite(v)?`${v} ms`:'—';};
  const fpsText=()=>typeof currentFps!=='undefined'&&currentFps?String(currentFps):'—';
  const statusInfo=()=>{const s=typeof statusMessage!=='undefined'?statusMessage.state:'connecting';if(s==='connected')return{cls:'good',text:'Conectado'};if(s==='login')return{cls:'warn',text:'Esperando login'};if(s==='offline')return{cls:'warn',text:'Sin conexión'};return{cls:'warn',text:'Conectando…'};};
  async function getData(){try{data=await ipcRenderer.invoke('hub:get-data',profileId);}catch(_){data=null;}applyTheme();}
  async function save(updates){try{const next=await ipcRenderer.invoke('hub:save-data',profileId,updates);if(next){data=next;render();}return next;}catch(e){toast(e?.message||'No se pudo guardar.');return null;}}
  async function clientAction(action,payload){try{return await ipcRenderer.invoke('client:panel-action',profileId,action,payload);}catch(e){toast(e?.message||'No se pudo ejecutar.');return null;}}
  async function quickAction(action){try{return await ipcRenderer.invoke('hub:quick-action',profileId,action);}catch(e){return{ok:false,message:e?.message||'No se pudo ejecutar.'};}}
  async function detectGame(){try{const g=await ipcRenderer.invoke('client:game-context',profileId);currentGame=g||{id:'unknown',label:'No detectado',confidence:0};}catch(_){currentGame={id:'unknown',label:'No detectado',confidence:0};}if(currentGame.id!=='sendero'){await clientAction('game-assist',{action:'reset',gameId:currentGame.id||'unknown'});}return currentGame;}
  function toast(message){const el=root?.querySelector('.hub-toast');if(!el)return;el.textContent=String(message||'Listo.');el.classList.add('show');clearTimeout(el._timer);el._timer=setTimeout(()=>el.classList.remove('show'),1700);}
  function applyTheme(){if(!root||!data)return;root.className=`${open?'open ':''}theme-crystal${data.streamerMode?' hub-private':''}${data.dock==='left'?' dock-left':''}${clientSettings?.performanceMode?' perf-lite':''}`;const b=q('#__bb_hub_button');if(b)b.style.display=clientSettings?.cleanMode?'none':'grid';}
  const tabDefs=[['home','⌂','Inicio'],['smartbar','✦','Smart Bar'],['autoclick','⊕','Autoclick'],['alerts','🔔','Avisos'],['games','🎮','Minijuegos'],['assist','🛠','Herramientas'],['tools','⚙','Cliente'],['performance','◈','Rendimiento'],['appearance','◐','Vista']];
  function renderTabs(){tabs.innerHTML=tabDefs.map(([id,icon,label])=>`<button class="hub-tab ${tab===id?'active':''}" data-tab="${id}"><span class="ti">${icon}</span><span>${label}</span></button>`).join('');tabs.querySelectorAll('[data-tab]').forEach(b=>b.onclick=async()=>{tab=b.dataset.tab;if(tab==='games'||tab==='assist')await detectGame();if(tab==='autoclick'||tab==='smartbar')acLoad();if(tab==='alerts')alLoad();render();});}
  const actionButton=(label,action,cls='hub-btn')=>`<button class="${cls}" data-action="${esc(action)}">${label}</button>`;
  const gameCatalog=[
    {id:'sendero',label:'Sendero Oculto',icon:'🛤️',desc:'Screen Marker: pinta caminos y pon marcas sobre el tablero. Clic derecho o Espacio para pasar del lápiz al ratón.',tool:'screen-marker'},
    {id:'simon',label:'Simón Dice',icon:'🧠',desc:'Bloc de memoria manual para apuntar la secuencia que tú observas.',tool:'sequence'},
    {id:'papa',label:'Papa Caliente',icon:'🥔',desc:'Temporizador visual para controlar la ronda sin tocar el cliente.',tool:'timer'},
  ];
  function selectedGame(){return gameCatalog.find(g=>g.id===currentGame.id)||{id:currentGame.id||'unknown',label:currentGame.label||'No detectado',icon:'🎮',desc:'No hay una herramienta específica para este juego.',tool:null};}
  function renderHome(){const st=data.stats||{},si=statusInfo();return `<div class="hub-section"><div class="hub-hero"><div class="hub-hero-row"><div class="hub-hero-avatar">BB</div><div><h2>${data.streamerMode?'Jugador':esc(profileLabel)}</h2><p>Centro de control del cliente</p></div><div class="hub-session"><strong id="hubSessionClock">${fmtClock(currentSessionSeconds())}</strong><span>sesión actual</span></div></div></div></div><div class="hub-grid4 hub-section"><div class="hub-stat"><strong>${fmtTime(todayPlayedSeconds())}</strong><span>Hoy</span></div><div class="hub-stat"><strong>${fmtTime(st.totalSeconds)}</strong><span>Tiempo total</span></div><div class="hub-stat"><strong>${Number(st.sessions)||0}</strong><span>Sesiones</span></div><div class="hub-stat"><strong>${Number(st.currentStreak)||0}</strong><span>Racha</span></div></div><div class="hub-section"><div class="hub-label">CENTRO RÁPIDO</div><div class="hub-actions">${actionButton('✦ Smart Bar','smartbar','hub-btn primary')}${actionButton('🎮 Minijuegos','games')}${actionButton('◈ Rendimiento','performance')}${actionButton('⚙ Cliente','tools')}${actionButton('⛶ Pantalla completa','fullscreen')}${actionButton('↻ Recargar','reload')}</div></div><div class="hub-section"><div class="hub-label">ESTADO</div><div class="hub-meta-card"><div class="hub-meta-row"><span>Cliente</span><strong class="private-hide">${si.text}</strong></div><div class="hub-meta-row"><span>Minijuego detectado</span><strong>${esc(currentGame.label)}</strong></div><div class="hub-meta-row"><span>Ping al servidor</span><strong>${pingText()}</strong></div><div class="hub-meta-row"><span>FPS</span><strong>${fpsText()}</strong></div><div class="hub-meta-row"><span>Memoria JS</span><strong>${heapText()}</strong></div></div></div>`;}
  function renderGames(){return `<div class="hub-section"><div class="hub-label">MINIJUEGOS</div><div class="hub-meta-card"><div class="hub-meta-row"><span>Detectado</span><strong>${esc(currentGame.label)}</strong></div><div class="hub-small">Cada juego tendrá únicamente las herramientas que realmente tengan sentido para su mecánica. El Screen Marker está reservado a Sendero Oculto.</div></div></div><div class="hub-game-grid">${gameCatalog.map(g=>`<div class="hub-game-card"><strong>${g.icon} ${g.label}</strong><p>${g.desc}</p><span class="tag">${g.id===currentGame.id?'ACTUAL':(g.tool?'MÓDULO':'SIN HERRAMIENTA')}</span><div style="margin-top:9px">${g.id==='sendero'?`<button class="hub-btn primary" data-marker="marker-open">✎ Abrir Screen Marker</button>`:g.tool?actionButton('Abrir módulo',`select-game:${g.id}`,'hub-btn '+(g.id===currentGame.id?'primary':'')):`<button class="hub-btn" disabled style="opacity:.45;cursor:not-allowed">Sin herramienta</button>`}</div></div>`).join('')}</div>`;}
  function renderAssist(){const g=selectedGame();const isSendero=g.id==='sendero';const sendero=isSendero?`<div class="sendero-card"><div class="sendero-head"><div><strong>🛤️ Sendero Oculto · Screen Marker</strong><span>Una barra dentro del juego para pintar caminos y poner marcas (✕ ✓ ? ◎), y volver al ratón al instante.</span></div><div class="sendero-badge">MANUAL</div></div>
      <div class="hub-row" style="margin-top:10px"><button class="hub-btn primary" data-marker="marker-open">✎ Abrir Screen Marker</button><button class="hub-btn" data-marker="marker-clear">🗑 Borrar dibujo</button><button class="hub-btn" data-marker="marker-close">× Cerrar</button></div>
      <div class="hub-small" style="margin-top:9px"><b>Cambio rápido lápiz ⇄ ratón:</b> clic derecho sobre el juego o la tecla <b>Espacio</b>. En modo ratón, mantén <b>Shift</b> para dibujar mientras la pulsas. <b>Ctrl+Z</b> deshace. La barra se arrastra desde ⋮⋮ (doble clic la recoloca).</div></div>`:'';const gameSpecific=g.id==='simon'?`<div class="assist-card"><strong>🧠 Memoria manual</strong><span>Registra la secuencia que tú ves con colores.</span><div class="assist-grid" style="grid-template-columns:repeat(2,1fr);margin-top:7px"><button class="assist-chip" data-seq="rojo">🔴 Rojo</button><button class="assist-chip" data-seq="azul">🔵 Azul</button><button class="assist-chip" data-seq="verde">🟢 Verde</button><button class="assist-chip" data-seq="amarillo">🟡 Amarillo</button></div><div class="hub-small" id="sequenceText" style="margin-top:8px">Secuencia: —</div><button class="hub-btn" data-assist-action="sequence-clear">Limpiar secuencia</button></div>`:g.id==='papa'?`<div class="assist-card"><strong>🥔 Papa Caliente · Temporizador</strong><span>Temporizador visual independiente. No intercepta el ratón del juego.</span></div>`:`<div class="assist-card"><strong>${g.icon} ${g.label}</strong><span>No hay Screen Marker para este juego. El sistema reserva el lápiz exclusivamente para Sendero Oculto para no interferir con la navegación ni con la jugabilidad.</span></div>`;const timerAllowed=g.id==='papa'||g.id==='sendero';return `<div class="hub-section"><div class="hub-label">AYUDAS DEL JUEGO</div><div class="hub-assist-hero"><div class="hub-meta-row"><span>Juego actual</span><strong>${esc(g.label)}</strong></div><div class="assist-tip">${isSendero?'El Screen Marker solo se activa para Sendero Oculto.':'Esta pantalla no activa el Screen Marker.'}</div>${sendero}</div></div>${timerAllowed?`<div class="hub-section"><div class="hub-label">TEMPORIZADOR</div><div class="hub-actions"><button class="hub-btn" data-assist-timer="15">15 s</button><button class="hub-btn" data-assist-timer="30">30 s</button><button class="hub-btn" data-assist-timer="60">60 s</button><button class="hub-btn" data-assist-timer="90">90 s</button><button class="hub-btn" data-assist-action="timer-hide">Ocultar</button><button class="hub-btn danger" data-assist-action="reset">Reset</button></div></div>`:''}<div class="assist-grid hub-section">${gameSpecific}<div class="assist-card"><strong>↩ Volver al juego</strong><span>Cierra el Hub y deja el cliente listo para jugar.</span><button class="hub-btn primary" data-action="focus-game">Enfocar BoomBang</button></div><div class="assist-card"><strong>🧼 Limpieza</strong><span>Al cambiar de juego, cualquier Screen Marker activo se desactiva automáticamente.</span><button class="hub-btn" data-assist-action="reset">Limpiar</button></div></div>`;}
  function renderTools(){const s=clientSettings||{};return `<div class="hub-section"><div class="hub-label">VENTANA Y CLIENTE</div><div class="hub-actions">${actionButton('⛶ Pantalla completa','fullscreen','hub-btn primary')}${actionButton('◎ Enfocar','focus-game')}${actionButton('↻ Recargar','reload')}<button class="hub-btn" id="hubClearCache" title="Borra los archivos temporales del juego de esta cuenta y recarga. No cierra la sesión.">🧹 Borrar caché</button>${actionButton('⌂ Launcher','show-launcher')}${actionButton('✦ Inicio','home')}${actionButton('× Cerrar Hub','close-hub')}</div></div><div class="hub-section"><div class="hub-label">AJUSTES</div>${[['showPerformance','Mostrar FPS','Indicador de rendimiento dentro del cliente.'],['showStatusBar','Barra de estado','Conexión, latencia y sesión.'],['cleanMode','Modo limpio','Oculta botones flotantes del launcher.'],['alwaysOnTop','Siempre encima','Mantiene la ventana por encima de otras.'],['muted','Silenciar','Silencia BoomBang.'],['performanceMode','Modo rendimiento','Reduce efectos del Hub y fuerza el cliente a 60 FPS.']].map(([id,label,help])=>`<div class="hub-check"><div><strong>${label}</strong><span>${help}</span></div><input type="checkbox" data-client-setting="${id}" ${s[id]?'checked':''}></div>`).join('')}</div>`;}
  function renderPerformance(){return `<div class="hub-grid4 hub-section"><div class="hub-stat"><strong>${fpsText()}</strong><span>FPS</span></div><div class="hub-stat"><strong>${heapText()}</strong><span>Memoria JS</span></div><div class="hub-stat"><strong>${Math.round(Number(clientSettings.zoom)||100)}%</strong><span>Zoom</span></div><div class="hub-stat"><strong>${esc(clientSettings.fitMode||'contain')}</strong><span>Vista</span></div></div><div class="hub-section"><div class="hub-label">PERFILES DE RENDIMIENTO</div><div class="hub-actions"><button class="hub-btn ${!clientSettings.performanceMode?'active':''}" data-perf-profile="balanced">⚖ Equilibrado</button><button class="hub-btn ${clientSettings.performanceMode?'primary':''}" data-perf-profile="performance">⚡ Rendimiento</button><button class="hub-btn" data-perf-profile="balanced-lite">◌ Ahorro</button></div></div><div class="hub-section"><div class="hub-label">DETALLES</div><div class="hub-meta-card"><div class="hub-meta-row"><span>FPS del renderer</span><strong>60</strong></div><div class="hub-meta-row"><span>Throttling en segundo plano</span><strong>Desactivado</strong></div><div class="hub-meta-row"><span>GPU raster</span><strong>Activado si está disponible</strong></div><div class="hub-meta-row"><span>Zero-copy</span><strong>Activado si está disponible</strong></div></div></div>`;}
  const SB_CATALOG=[{id:'red',label:'Rojo',css:'#e3202c',wins:0},{id:'pink',label:'Rosa',css:'#ff2fa3',wins:1},{id:'orange',label:'Naranja',css:'#ff7a1a',wins:10},{id:'green',label:'Verde',css:'#2fe03c',wins:25},{id:'blue',label:'Azul',css:'#5b8dff',wins:50},{id:'white',label:'Blanco',css:'#ececf0',wins:100},{id:'lavender',label:'Lila',css:'#c7b3ff',wins:250},{id:'purple',label:'Morado',css:'#a321f0',wins:500},{id:'olive',label:'Olivo',css:'#8c9c12',wins:1000},{id:'darkred',label:'Rojo oscuro',css:'#a10f12',wins:2000},{id:'brown',label:'Marrón',css:'#c2493c',wins:3000},{id:'teal',label:'Celeste',css:'#3fd8d8',wins:4000},{id:'gray',label:'Gris',css:'#9c9ca2',wins:5000},{id:'black',label:'Negro',css:'#2c2c30',wins:8000},{id:'gold',label:'Dorado',css:'#ffac1f',wins:10000},{id:'sage',label:'Transparente',css:'#3f6a64',wins:13000},{id:'lightpink',label:'Colorines',css:'#d9dde2',wins:20000}];
  const sbWins=n=>`${Number(n).toLocaleString('es-ES')} ${n===1?'victoria':'victorias'}`;
  const sbColor=id=>SB_CATALOG.find(c=>c.id===id)||null;
  const SB_DEFAULT=[{id:'gg',type:'text',label:'GG',text:'gg'},{id:'srt',type:'text',label:'SRT',text:'srt {user}'},{id:'gold',type:'upper',color:'gold'},{id:'black',type:'upper',color:'black'},{id:'brown',type:'upper',color:'brown'},{id:'orange',type:'upper',color:'orange'}];
  const SB_MAX=10;
  function sbNormalize(raw){
    if(!Array.isArray(raw))return null;
    const out=[],seen=new Set();
    for(const r of raw.slice(0,SB_MAX)){
      if(!r||typeof r!=='object')continue;
      if(r.type==='upper'){if(!sbColor(r.color)||seen.has(r.color))continue;seen.add(r.color);out.push({id:r.color,type:'upper',color:r.color});}
      else if(r.type==='text'){
        const text=String(r.text==null?'':r.text).slice(0,120);if(!text.trim())continue;
        let id=/^[\w-]{1,24}$/.test(String(r.id||''))?String(r.id):'t'+Math.random().toString(36).slice(2,8);
        if(seen.has(id)||sbColor(id))id='t'+Math.random().toString(36).slice(2,8);seen.add(id);
        out.push({id,type:'text',label:String(r.label==null?'':r.label).trim().slice(0,10)||text.trim().slice(0,6),text});
      }
    }
    return out;
  }
  function sbItems(){const n=sbNormalize(clientSettings.smartBarItems);if(n!==null)return n;const sc=data.shortcuts||{};return SB_DEFAULT.map(i=>i.type==='text'?{...i,text:sc[i.id]||i.text}:{...i});}
  let sbEdit=null,sbProfiles=null;
  async function sbLoadProfiles(){try{const list=await ipcRenderer.invoke('profiles:list');sbProfiles=(Array.isArray(list)?list:[]).filter(p=>String(p.id)!==String(profileId)).map(p=>({id:p.id,name:p.name}));}catch(_){sbProfiles=[];}if(tab==='smartbar')render();}
  const sbSave=items=>setClientSetting('smartBarItems',items);
  const HK_DEFAULTS={srt:'Ctrl+Shift+S',gg:'Ctrl+Shift+G',gold:'Ctrl+Shift+1',black:'Ctrl+Shift+2',brown:'Ctrl+Shift+3',orange:'Ctrl+Shift+4',toggle:'Ctrl+Shift+B'};
  const HK_KEYS={Backquote:'`',Minus:'-',Equal:'=',Comma:',',Period:'.',Slash:'/',Semicolon:';',Quote:"'",BracketLeft:'[',BracketRight:']',Backslash:'\\'};
  const hkLabel=id=>{if(id==='toggle')return 'Mostrar / ocultar la barra';const it=sbItems().find(i=>i.id===id);if(!it)return id;return it.type==='text'?`Botón «${it.label}»`:`Upper ${sbColor(it.color).label}`;};
  const hkNow=()=>{const c=clientSettings.hotkeys&&typeof clientSettings.hotkeys==='object'?clientSettings.hotkeys:{};const o={};for(const it of sbItems())o[it.id]=typeof c[it.id]==='string'?c[it.id]:(HK_DEFAULTS[it.id]||'');o.toggle=typeof c.toggle==='string'?c.toggle:HK_DEFAULTS.toggle;return o;};
  function hkCombo(e){const code=String(e.code||'');if(!code||/^(Control|Shift|Alt|Meta|OS)(Left|Right)?$/.test(code))return null;let key=HK_KEYS[code]||code;const m=code.match(/^Key([A-Z])$/)||code.match(/^Digit(\d)$/);if(m)key=m[1];else if(/^Numpad/.test(code))key='Num'+code.slice(6);const parts=[];if(e.ctrlKey)parts.push('Ctrl');if(e.altKey)parts.push('Alt');if(e.shiftKey)parts.push('Shift');if(e.metaKey)parts.push('Meta');parts.push(key);return parts.join('+');}
  let hkListener=null;
  function stopHkCapture(){if(hkListener){window.removeEventListener('keydown',hkListener,true);hkListener=null;}window.__BB_HOTKEY_CAPTURE__=false;}
  function startHkCapture(action,btn){
    stopHkCapture();window.__BB_HOTKEY_CAPTURE__=true;btn.textContent='Pulsa la combinación…  (Esc cancela)';btn.classList.add('listening');
    hkListener=e=>{
      e.preventDefault();e.stopImmediatePropagation();
      if(e.code==='Escape'){stopHkCapture();render();return;}
      const combo=hkCombo(e);if(!combo)return;
      const cur=hkNow();const clash=Object.keys(cur).find(k=>k!==action&&cur[k]===combo);
      if(clash){toast(`«${combo}» ya la usa: ${hkLabel(clash)}.`);return;}
      if(acKeysNow().includes(combo)){toast(`${combo} la usa el autoclick. Elige otra o cámbiala en la pestaña Autoclick.`);return;}
      stopHkCapture();
      const plain=!/(Ctrl|Alt|Meta)\+/.test(combo)&&!/(^|\+)F\d{1,2}$/.test(combo);
      setClientSetting('hotkeys',{...(clientSettings.hotkeys||{}),...cur,[action]:combo}).then(()=>toast(plain?`Atajo guardado: ${combo} (sin Ctrl/Alt no funciona mientras escribes en el chat)`:`Atajo guardado: ${combo}`));
    };
    window.addEventListener('keydown',hkListener,true);
  }
  function renderSmartbar(){
    const items=sbItems(),hk=hkNow(),uc=clientSettings.upperColors||{plus:null,colors:{}};
    if(sbEdit&&sbEdit!=='new'&&!items.some(i=>i.id===sbEdit))sbEdit=null;
    if(sbProfiles===null)setTimeout(sbLoadProfiles,0);
    const uppers=items.filter(i=>i.type==='upper');
    const ready=uppers.length&&uppers.every(i=>uc.colors&&uc.colors[i.color])&&uc.plus;
    const free=SB_CATALOG.filter(c=>!uppers.some(i=>i.color===c.id));
    const editing=sbEdit==='new'?{label:'',text:''}:items.find(i=>i.id===sbEdit);
    const rows=items.map((it,i)=>{
      const c=it.type==='upper'?sbColor(it.color):null;
      return `<div class="sb-item">${it.type==='text'?`<span class="sb-chip">${esc(it.label)}</span>`:`<i class="sb-dot" data-color="${c.id}" style="--c:${c.css}"></i>`}<div class="sb-color-name"><strong>${it.type==='text'?esc(it.text):'Upper '+c.label+' · '+sbWins(c.wins)}</strong><span>${it.type==='text'?'Texto al chat':'Upper rápido'} · ${esc(hk[it.id]||'sin atajo')}</span></div>${it.type==='text'?`<button class="hub-mini" data-sb-test="${it.id}" title="Enviar ahora">Probar</button><button class="hub-mini" data-sb-edit="${it.id}" title="Editar">✎</button>`:''}<button class="hub-mini" data-sb-move="${i}:-1" ${i===0?'disabled':''} title="Subir">▲</button><button class="hub-mini" data-sb-move="${i}:1" ${i===items.length-1?'disabled':''} title="Bajar">▼</button><button class="hub-mini" data-sb-del="${it.id}" title="Quitar de la barra">🗑</button></div>`;
    }).join('');
    const form=editing?`<div class="sb-edit"><div class="hub-label">${sbEdit==='new'?'NUEVO BOTÓN DE TEXTO':'EDITAR BOTÓN'}</div><div class="hub-row"><input id="sbLabel" class="hub-input" maxlength="10" placeholder="Nombre en la barra (ej. GG)" value="${esc(editing.label)}" style="max-width:190px"><input id="sbText" class="hub-input" maxlength="120" placeholder="Mensaje (ej. srt {user})" value="${esc(editing.text)}"></div><div class="hub-small" style="margin:8px 0">Usa <b>{user}</b> para poner el nombre de la ficha abierta. Se envía al chat público.</div><div class="hub-row"><button class="hub-btn primary" id="sbSaveItem">Guardar botón</button><button class="hub-btn" id="sbCancel">Cancelar</button></div></div>`:'';
    const uppersRows=uppers.length?uppers.map(it=>{const c=sbColor(it.color);return `<div class="sb-color"><i class="sb-dot" data-color="${c.id}" style="--c:${c.css}"></i><div class="sb-color-name"><strong>${c.label} <small class="sb-wins">${sbWins(c.wins)}</small></strong><span>${uc.colors&&uc.colors[it.color]?'<em class="ok">calibrado ✓</em>':'<em class="no">sin calibrar</em>'} · ${esc(hk[it.id]||'sin atajo')}</span></div><button class="hub-mini" data-sb-upper="${it.color}">Probar</button><button class="hub-mini" data-sb-learn="color:${it.color}">Calibrar</button></div>`;}).join(''):'<div class="hub-empty">No hay colores de upper en la barra. Añade uno arriba.</div>';
    return `<div class="hub-section"><div class="hub-label">SMART BAR</div><div class="hub-check"><div><strong>Mostrar la Smart Bar en el juego</strong><span>Se arrastra y se guarda por perfil. Doble clic en ⋮⋮ la centra.</span></div><input data-client-setting="smartBar" type="checkbox" ${clientSettings.smartBar!==false?'checked':''}></div>
      <div class="hub-check" style="margin-top:8px"><div><strong>Mostrar el ping</strong><span>Ping al servidor dentro de la barra.</span></div><input data-client-setting="smartBarShowPing" type="checkbox" ${clientSettings.smartBarShowPing!==false?'checked':''}></div>
      <div class="hub-check" style="margin-top:8px"><div><strong>Mostrar el engranaje</strong><span>Atajo al BB Hub (si lo quitas, el Hub sigue en el launcher).</span></div><input data-client-setting="smartBarShowGear" type="checkbox" ${clientSettings.smartBarShowGear!==false?'checked':''}></div></div>
    <div class="hub-section"><div class="hub-label">BOTONES DE LA BARRA (${items.length}/${SB_MAX})</div><div class="sb-intro">Ordénalos con ▲▼, edita el texto con ✎ o quítalos con 🗑. Puedes tener los botones de texto y los colores de upper que quieras.</div>
      <div class="sb-items">${rows||'<div class="hub-empty">La barra está vacía. Añade un botón.</div>'}</div>${form}
      <div class="hub-row" style="margin-top:10px"><button class="hub-btn" id="sbAddText" ${items.length>=SB_MAX?'disabled':''}>+ Botón de texto</button><select id="sbColorSel" class="hub-select" ${free.length&&items.length<SB_MAX?'':'disabled'}>${free.map(c=>`<option value="${c.id}">${c.label} · ${sbWins(c.wins)}</option>`).join('')}</select><button class="hub-btn" id="sbAddUpper" ${free.length&&items.length<SB_MAX?'':'disabled'}>+ Color de upper</button><button class="hub-btn" id="sbResetItems">Restablecer barra</button></div></div>
    <div class="hub-section"><div class="hub-label">UPPER RÁPIDO · CALIBRACIÓN</div><div class="sb-intro">Abre la ficha de un jugador y pulsa un color: la barra pulsa el <b>+</b> y elige el color por ti. Se calibra <b>una sola vez</b> por color.</div>
      <div class="sb-colors">${uppersRows}</div>
      <div class="sb-plus"><div class="sb-color-name"><strong>Botón «+» del upper</strong><span>${uc.plus?'<em class="ok">calibrado ✓</em>':'<em class="no">sin calibrar</em>'}</span></div><button class="hub-mini" data-sb-learn="plus">Calibrar +</button></div>
      <div class="hub-row" style="margin-top:11px"><button class="hub-btn primary" data-sb-learn="all" ${uppers.length?'':'disabled'}>${ready?'↻ Recalibrar todo':'✦ Calibrar todo (guiado)'}</button><button class="hub-btn" data-sb-learn="reset">Borrar calibración</button></div>
      <div class="hub-small" style="margin-top:9px">Durante la calibración se te dirá qué pulsar. Los clics de <b>color</b> no se envían al juego (no se da ningún upper). Esc cancela.</div></div>
    <div class="hub-section"><div class="hub-label">ATAJOS DE TECLADO</div><div class="sb-intro">Pulsa un atajo y luego la combinación que quieras (por ejemplo <b>F2</b>, <b>Alt+S</b> o <b>Ctrl+Shift+S</b>). <b>✕</b> lo quita.</div><div class="sb-hks">${Object.keys(hk).map(k=>`<div class="sb-hk"><span>${esc(hkLabel(k))}</span><button class="hub-mini sb-key" data-hk="${k}">${esc(hk[k]||'— sin atajo —')}</button><button class="hub-mini" data-hk-clear="${k}" title="Quitar atajo">✕</button></div>`).join('')}</div><div class="hub-row" style="margin-top:10px"><button class="hub-btn" id="hkReset">Restablecer atajos</button></div><div class="hub-small" style="margin-top:8px">Una tecla sola (sin Ctrl/Alt) solo funciona cuando no estás escribiendo en el chat; las teclas F1–F12 funcionan siempre.</div></div>
    <div class="hub-section"><div class="hub-label">PING</div><div class="hub-row"><input id="pingHost" class="hub-input" value="${esc(clientSettings.pingHost||'144.217.195.55')}" placeholder="144.217.195.55"><button class="hub-btn" id="savePingHost">Guardar</button></div><div class="hub-small" style="margin-top:8px">Servidor al que se mide el ping de la barra (igual que <i>ping 144.217.195.55</i>).</div></div>
    <div class="hub-section"><div class="hub-label">COPIAR A OTROS PERFILES</div>${sbProfiles===null?'<div class="hub-small">Cargando perfiles…</div>':!sbProfiles.length?'<div class="hub-empty">No tienes otros perfiles en el launcher.</div>':`<div class="sb-intro">Copia esta configuración a tus otras cuentas para no repetirla.</div><div class="sb-copy-list">${sbProfiles.map(p=>`<label class="sb-copy"><input type="checkbox" data-copy-to="${esc(p.id)}" checked><span>${esc(p.name)}</span></label>`).join('')}</div><div class="sb-copy-parts"><label class="sb-copy"><input type="checkbox" id="copyBar" checked><span>Botones, atajos y ping</span></label><label class="sb-copy"><input type="checkbox" id="copyCalib" checked><span>Calibración del upper</span></label></div><div class="hub-row" style="margin-top:10px"><button class="hub-btn primary" id="copySettings">Copiar a los perfiles marcados</button></div><div class="hub-small" style="margin-top:8px">Si un perfil está abierto, se aplica al momento. La calibración solo sirve si la ventana del juego tiene un tamaño parecido.</div>`}</div>`;
  }
  // ---------------------------------------------------------------- Autoclick (global: same for every profile)
  let acState=null,acListener=null,acMouse=null,acTimer=null,acSaveTimer=null;
  async function acLoad(){try{acState=await ipcRenderer.invoke('autoclick:get');}catch(_){acState=null;}if(tab==='autoclick')render();}
  const acKeysNow=()=>acState&&acState.keys?Object.values(acState.keys):['F1','F2','F3'];
  const AC_ROLES=[['set','Guardar posición','Pon el ratón donde quieras los clics y pulsa esta tecla.'],['start','Empezar','Empieza a hacer clics en la posición guardada.'],['stop','Parar','Deja de hacer clics.']];
  const AC_NAMES={Mouse3:'Rueda (clic central)',Mouse4:'Botón lateral atrás',Mouse5:'Botón lateral adelante',ArrowLeft:'Flecha ←',ArrowUp:'Flecha ↑',ArrowRight:'Flecha →',ArrowDown:'Flecha ↓',PageUp:'Re Pág',PageDown:'Av Pág',Insert:'Insert',Delete:'Supr',Home:'Inicio',End:'Fin',Pause:'Pausa',ScrollLock:'Bloq Despl'};
  const acKeyLabel=k=>AC_NAMES[k]||k;
  const AC_PLAIN=['Insert','Delete','Home','End','PageUp','PageDown','ArrowLeft','ArrowUp','ArrowRight','ArrowDown','Pause','ScrollLock'];
  function acKeyFromEvent(e){const code=String(e.code||'');let m;if((m=code.match(/^F(\d{1,2})$/))&&+m[1]>=1&&+m[1]<=12)return code;if((m=code.match(/^Key([A-Z])$/)))return m[1];if((m=code.match(/^Digit(\d)$/)))return m[1];if(AC_PLAIN.includes(code))return code;return null;}
  const acBlock=e=>{if(e.button===1||e.button===3||e.button===4){e.preventDefault();e.stopImmediatePropagation();}};
  function stopAcCapture(resume=true){clearTimeout(acTimer);if(acListener){window.removeEventListener('keydown',acListener,true);window.removeEventListener('mousedown',acMouse,true);window.removeEventListener('mouseup',acBlock,true);window.removeEventListener('auxclick',acBlock,true);acListener=null;acMouse=null;window.__BB_HOTKEY_CAPTURE__=false;if(resume)ipcRenderer.invoke('autoclick:pause',false).catch(()=>{});}}
  async function acSave(patch,msg){try{acState=await ipcRenderer.invoke('autoclick:save',patch);if(msg)toast(msg);}catch(e){toast(String(e?.message||'No se pudo guardar.').replace(/^Error invoking remote method '[^']+': (Error: )?/,''));await acLoad();}if(tab==='autoclick')render();}
  function acAccept(role,key){
    const cur={...(acState?.keys||{set:'F3',start:'F1',stop:'F2'})};
    const other=Object.keys(cur).find(r=>r!==role&&cur[r]===key);
    if(other){toast(`«${acKeyLabel(key)}» ya es la tecla de «${AC_ROLES.find(x=>x[0]===other)[1]}».`);return false;}
    const hk=hkNow();const sb=Object.keys(hk).find(k=>hk[k]===key);
    if(sb){toast(`«${acKeyLabel(key)}» ya la usa la Smart Bar (${hkLabel(sb)}). Elige otra.`);return false;}
    stopAcCapture(false);
    const risky=/^[A-Z0-9]$/.test(key);
    acSave({keys:{[role]:key}},risky?`Guardado: ${key}. Ojo: el autoclick la detecta en todo Windows, también mientras escribes.`:`Guardado: ${acKeyLabel(key)}.`);
    return true;
  }
  function startAcCapture(role,btn){
    stopHkCapture();stopAcCapture(false);window.__BB_HOTKEY_CAPTURE__=true;
    btn.textContent='Pulsa una tecla o botón del ratón…  (Esc cancela)';btn.classList.add('listening');
    ipcRenderer.invoke('autoclick:pause',true).catch(()=>{});
    acListener=e=>{e.preventDefault();e.stopImmediatePropagation();if(e.repeat)return;if(e.code==='Escape'){stopAcCapture();render();return;}
      if(e.ctrlKey||e.altKey||e.metaKey||/^(Control|Shift|Alt|Meta|OS)/.test(String(e.code||'')))return;
      const key=acKeyFromEvent(e);if(!key){toast('Esa tecla no se puede usar. Prueba F1–F12, una letra, un número, Insert, Inicio, Re Pág…');return;}acAccept(role,key);};
    acMouse=e=>{const key=e.button===1?'Mouse3':e.button===3?'Mouse4':e.button===4?'Mouse5':null;if(!key)return;e.preventDefault();e.stopImmediatePropagation();acAccept(role,key);};
    window.addEventListener('keydown',acListener,true);window.addEventListener('mousedown',acMouse,true);window.addEventListener('mouseup',acBlock,true);window.addEventListener('auxclick',acBlock,true);
    acTimer=setTimeout(()=>{stopAcCapture();render();},29000);
  }
  function renderAutoclick(){
    if(!acState){setTimeout(acLoad,0);return '<div class="hub-section"><div class="hub-small">Cargando…</div></div>';}
    const k=acState.keys,iv=acState.interval;
    return `<div class="hub-section"><div class="hub-label">AUTOCLICK</div><div class="hub-check"><div><strong>Activar el autoclick</strong><span>Funciona en segundo plano mientras el launcher está abierto. Esta configuración es la misma para todos tus perfiles.</span></div><input id="acEnabled" type="checkbox" ${acState.enabled?'checked':''}></div>
      <div class="sb-intro" style="margin-top:10px">Cómo se usa: <b>${esc(acKeyLabel(k.set))}</b> guarda la posición del ratón · <b>${esc(acKeyLabel(k.start))}</b> empieza · <b>${esc(acKeyLabel(k.stop))}</b> para. Dentro de BoomBang los clics van directos al juego y tu ratón queda libre.</div></div>
    <div class="hub-section ${acState.enabled?'':'ac-off'}"><div class="hub-label">VELOCIDAD</div><div class="sb-intro">Milisegundos entre cada tanda de clics. <b>1 = máximo</b> (8 clics por tanda); a partir de 2 ms, 6 clics por tanda como el original. Si el PC va lento o se traba, súbelo (por ejemplo 30–100).</div>
      <div class="ac-speed"><input type="range" id="acRange" min="1" max="500" step="1" value="${Math.min(500,iv)}" aria-label="Intervalo del autoclick"><input type="number" id="acInterval" class="hub-input" min="1" max="1000" step="1" value="${iv}" aria-label="Intervalo en milisegundos"><span>ms</span></div>
      <div class="hub-small" id="acSpeedNote" style="margin-top:6px">${iv<=1?'Modo máximo.':iv<30?'Rápido.':iv<=100?'Equilibrado: buena opción si el PC se traba.':'Lento.'}</div></div>
    <div class="hub-section ${acState.enabled?'':'ac-off'}"><div class="hub-label">TECLAS</div><div class="sb-intro">Pulsa un botón y luego la tecla (o un botón del ratón: la rueda o los laterales). Mejor teclas que no uses para escribir, como F1–F12: el autoclick las detecta en todo Windows.</div>
      <div class="sb-hks">${AC_ROLES.map(([r,label,hint])=>`<div class="sb-hk" title="${esc(hint)}"><span>${esc(label)}</span><button class="hub-mini sb-key" data-ac-key="${r}">${esc(acKeyLabel(k[r]))}</button></div>`).join('')}</div>
      <div class="hub-row" style="margin-top:10px"><button class="hub-btn" id="acKeysReset">Restablecer (F3 · F1 · F2)</button></div></div>`;
  }
  function bindAutoclick(){
    const en=q('#acEnabled');if(en)en.onchange=()=>acSave({enabled:en.checked},en.checked?'Autoclick activado.':'Autoclick desactivado.');
    const rg=q('#acRange'),nb=q('#acInterval');
    const note=v=>{const el=q('#acSpeedNote');if(el)el.textContent=v<=1?'Modo máximo.':v<30?'Rápido.':v<=100?'Equilibrado: buena opción si el PC se traba.':'Lento.';};
    const clamp=v=>{const n=Math.round(Number(v));return Number.isFinite(n)&&n>=1?Math.min(1000,n):1;};
    const commit=v=>{clearTimeout(acSaveTimer);acSaveTimer=setTimeout(()=>acSave({interval:clamp(v)},`Intervalo: ${clamp(v)} ms.`),250);};
    if(rg)rg.oninput=()=>{if(nb)nb.value=rg.value;note(Number(rg.value));};
    if(rg)rg.onchange=()=>commit(rg.value);
    if(nb)nb.oninput=()=>{const n=Math.round(Number(nb.value));if(Number.isFinite(n)&&n>=1){if(rg)rg.value=String(Math.min(500,n));note(n);}};
    if(nb)nb.onchange=()=>{nb.value=String(clamp(nb.value));commit(nb.value);};
    root.querySelectorAll('[data-ac-key]').forEach(el=>el.onclick=()=>startAcCapture(el.dataset.acKey,el));
    const rs=q('#acKeysReset');if(rs)rs.onclick=()=>{stopAcCapture(false);acSave({keys:null},'Teclas restablecidas: F3 · F1 · F2.');};
  }
  // ---------------------------------------------------------------- Avisos: soft chime when a learned object appears
  let alState=null,alRename=null,alVolTimer=null,alPixi=null;
  async function alLoad(){try{alState=await ipcRenderer.invoke('alerts:get');}catch(_){alState=null;}try{alPixi=await ipcRenderer.invoke('alerts:pixi-status',profileId);}catch(_){alPixi=null;}if(tab==='alerts')render();}
  async function alSave(patch,msg){try{alState=await ipcRenderer.invoke('alerts:save',patch);if(msg)toast(msg);}catch(e){toast('No se pudo guardar.');}if(tab==='alerts')render();}
  function renderAlerts(){
    if(!alState){setTimeout(alLoad,0);return '<div class="hub-section"><div class="hub-small">Cargando…</div></div>';}
    const items=alState.items||[];
    const thumb=it=>it.type==='visual'?`<img class="al-thumb" data-al-thumb="${esc(it.id)}" alt="">`:it.type==='pixi'?(it.thumb?`<img class="al-thumb" src="${esc(it.thumb)}" alt="">`:'<span class="sb-chip">✓</span>'):'<span class="sb-chip">🔔</span>';
    const sub=it=>it.type==='visual'?`Por su forma (menos fiable) · <b class="al-live" data-al-live="${esc(it.id)}">…</b>`
      :it.type==='pixi'?`<span title="${esc(it.key)}">Reconocido por el juego</span>${it.family?` · <label class="al-wide" title="Avisa también de otros objetos que el juego pone en el mismo sitio de la sala que este (útil si todos los del concurso van juntos)."><input type="checkbox" data-al-wide="${esc(it.key)}" ${it.wide?'checked':''}> también otros que caigan</label>`:''}`
      :esc(String(it.src).split('/').pop()||it.src);
    const rows=items.map((it,i)=>alRename===i
      ?`<div class="sb-item">${thumb(it)}<input id="alName" class="hub-input" maxlength="24" value="${esc(it.label)}" style="flex:1"><button class="hub-mini" data-al-name-save="${i}">Guardar</button><button class="hub-mini" data-al-name-cancel>✕</button></div>`
      :`<div class="sb-item">${thumb(it)}<div class="sb-color-name"><strong>${esc(it.label)}</strong><span>${sub(it)}</span></div><button class="hub-mini" data-al-rename="${i}" title="Cambiar nombre">✎</button><button class="hub-mini" data-al-del="${i}" title="Quitar">🗑</button></div>`).join('');
    const hasVisual=items.some(i=>i.type==='visual');
    const conn=!alPixi||alPixi.unknown?'<span class="al-conn">Abre BoomBang con este perfil para conectar.</span>':alPixi.ok?'<span class="al-conn ok">✓ Conectado con el juego: reconoce los objetos por su nombre interno.</span>':'<span class="al-conn no">Buscando el motor del juego…</span>';
    return `<div class="hub-section"><div class="hub-label">AVISO DE OBJETOS</div><div class="hub-small" style="margin:-2px 0 8px">${conn}</div><div class="hub-check"><div><strong>Avisar cuando caiga un objeto</strong><span>Suena un aviso suave y el botón del juego parpadea en la barra de tareas si estás en otra ventana. No recoge nada ni mueve el ratón: solo avisa.</span></div><input id="alEnabled" type="checkbox" ${alState.enabled?'checked':''}></div></div>
    <div class="hub-section ${alState.enabled?'':'ac-off'}"><div class="hub-label">VOLUMEN</div><div class="ac-speed"><input type="range" id="alVolume" min="0" max="100" step="5" value="${alState.volume}" aria-label="Volumen del aviso"><span id="alVolText">${alState.volume}%</span><button class="hub-mini" id="alTest">▶ Probar</button></div>
      ${hasVisual?`<div class="hub-row" style="margin-top:10px;align-items:center"><span class="hub-small" style="flex:1">Sensibilidad para objetos reconocidos por su forma. Si salta sin que haya nada, bájala; si no salta, súbela.</span><select id="alSens" class="hub-select">${[['alta','Alta'],['media','Media'],['baja','Baja']].map(([v,l])=>`<option value="${v}" ${alState.sensitivity===v?'selected':''}>${l}</option>`).join('')}</select></div>`:''}</div>
    <div class="hub-section"><div class="hub-label">OBJETOS (${items.length}/12)</div><div class="sb-intro">Cuando caiga un objeto, pulsa <b>Aprender objeto</b> y haz clic en él dentro del juego (ese clic no llega al juego). El launcher le pregunta al propio juego qué objeto es y guarda la imagen original de ese objeto (la del juego, no la de la pantalla): no mira colores ni formas en pantalla, así que la lluvia, la niebla o las sombras no le afectan. Marca <b>también otros que caigan</b> para que avise de cualquier objeto que el juego ponga en el mismo sitio.</div>
      <div class="sb-items">${rows||'<div class="hub-empty">Aún no hay objetos. Aprende el primero cuando caiga uno.</div>'}</div>
      ${hasVisual?'<div class="hub-small" id="alLiveNote" style="margin-top:8px">El porcentaje es cuánto se parece ahora mismo lo que hay en pantalla a cada objeto. El launcher aprende lo normal en cada sala (tarda unos segundos al entrar) y suena cuando el parecido sube por encima de lo normal; al lado tienes a partir de cuánto sonaría.</div>':''}
      <div class="hub-row" style="margin-top:10px"><button class="hub-btn primary" id="alLearn" ${items.length>=12?'disabled':''}>🔔 Aprender objeto</button><button class="hub-btn" id="alUpload" ${items.length>=12?'disabled':''}>🖼 Subir imagen</button><input type="file" id="alFile" accept="image/png,image/jpeg,image/webp,image/bmp" multiple hidden></div></div>`;
  }
  let alLiveTimer=null;
  async function alLiveTick(){
    if(tab!=='alerts'||!open&&!standalone()){clearInterval(alLiveTimer);alLiveTimer=null;return;}
    const els=root.querySelectorAll('[data-al-live]');if(!els.length){clearInterval(alLiveTimer);alLiveTimer=null;return;}
    let r=null;try{r=await ipcRenderer.invoke('alerts:scores',profileId);}catch(_){}
    els.forEach(el=>{const id=el.dataset.alLive;let txt='—',cls='';
      if(!r||!alState.enabled)txt='aviso apagado';else if(!r.watching)txt='—';else if(!r.ok||Date.now()-r.at>4000)txt='no se ve el juego';
      else if(id in r.scores){const v=Math.max(0,r.scores[id]),need=(r.need||{})[id]??0.8;txt=`ahora ${Math.round(v*100)}% · suena desde ${Math.round(need*100)}%`;cls=v>=need?'hit':v>=need-0.08?'near':'';}
      el.textContent=txt;el.className='al-live '+cls;});
  }
  // Objects are learned inside the game window: keep this tab in sync without having to close and reopen the Hub.
  let alSyncTimer=null;
  async function alSync(){
    if(tab!=='alerts'||(!open&&!standalone())||alRename!==null){if(tab!=='alerts'){clearInterval(alSyncTimer);alSyncTimer=null;}return;}
    try{const st=await ipcRenderer.invoke('alerts:get');const px=await ipcRenderer.invoke('alerts:pixi-status',profileId);
      if(JSON.stringify(st)!==JSON.stringify(alState)||JSON.stringify(px)!==JSON.stringify(alPixi)){const grew=st&&alState&&st.items.length>alState.items.length;alState=st;alPixi=px;render();if(grew)toast('✓ Objeto aprendido.');}}catch(_){}
  }
  function bindAlerts(){
    if(!alSyncTimer&&tab==='alerts')alSyncTimer=setInterval(alSync,1000);
    clearInterval(alLiveTimer);alLiveTimer=null;if(root.querySelector('[data-al-live]')){alLiveTick();alLiveTimer=setInterval(alLiveTick,1000);}
    root.querySelectorAll('[data-al-thumb]').forEach(async im=>{try{const u=await ipcRenderer.invoke('alerts:template',im.dataset.alThumb);if(u)im.src=u;}catch(_){}});
    root.querySelectorAll('[data-al-wide]').forEach(el=>el.onchange=()=>{const items=(alState.items||[]).map(x=>x.type==='pixi'&&x.key===el.dataset.alWide?{...x,wide:el.checked}:x);alSave({items},el.checked?'Avisará también de los objetos parecidos.':'Solo este objeto.');});
    const sens=q('#alSens');if(sens)sens.onchange=()=>alSave({sensitivity:sens.value},'Sensibilidad: '+sens.options[sens.selectedIndex].text+'.');
    const up=q('#alUpload'),file=q('#alFile');if(up&&file){up.onclick=()=>file.click();file.onchange=async()=>{const files=[...(file.files||[])].slice(0,12);let n=0;for(const f of files){try{const url=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(f);});alState=await ipcRenderer.invoke('alerts:add-image',url);n++;}catch(e){toast(String(e?.message||'No se pudo añadir.').replace(/^Error invoking remote method '[^']+': (Error: )?/,''));}}file.value='';if(n)toast(n===1?'Objeto añadido.':`${n} objetos añadidos.`);render();};}
    const en=q('#alEnabled');if(en)en.onchange=()=>alSave({enabled:en.checked},en.checked?'Aviso activado.':'Aviso desactivado.');
    const vol=q('#alVolume');if(vol){vol.oninput=()=>{const t=q('#alVolText');if(t)t.textContent=vol.value+'%';};vol.onchange=()=>{clearTimeout(alVolTimer);alVolTimer=setTimeout(()=>alSave({volume:Number(vol.value)}),150);};}
    const test=q('#alTest');if(test)test.onclick=async()=>{const v=Number(q('#alVolume')?.value??alState.volume);try{await ipcRenderer.invoke('alerts:test',profileId,v);}catch(_){}if(!v)toast('El volumen está a 0.');};
    const learn=q('#alLearn');if(learn)learn.onclick=async()=>{let ok=false;try{ok=await ipcRenderer.invoke('alerts:learn',profileId);}catch(_){}toast(ok?'Haz clic en el objeto dentro del juego.':'Abre BoomBang con este perfil para aprender un objeto.');if(ok&&!standalone())setTimeout(()=>toggle(false),350);};
    root.querySelectorAll('[data-al-del]').forEach(el=>el.onclick=()=>{const items=[...(alState.items||[])];items.splice(Number(el.dataset.alDel),1);alRename=null;alSave({items},'Objeto quitado.');});
    root.querySelectorAll('[data-al-rename]').forEach(el=>el.onclick=()=>{alRename=Number(el.dataset.alRename);render();const i=q('#alName');if(i){i.focus();i.select();}});
    const nameSave=root.querySelector('[data-al-name-save]');if(nameSave){const go=()=>{const i=Number(nameSave.dataset.alNameSave);const items=(alState.items||[]).map((x,k)=>k===i?{...x,label:(q('#alName')?.value||'').trim()||x.label}:x);alRename=null;alSave({items},'Nombre guardado.');};nameSave.onclick=go;const inp=q('#alName');if(inp)inp.onkeydown=e=>{if(e.key==='Enter')go();if(e.key==='Escape'){alRename=null;render();}};}
    const nameCancel=root.querySelector('[data-al-name-cancel]');if(nameCancel)nameCancel.onclick=()=>{alRename=null;render();};
  }
  function renderAppearance(){const mode=data.openMode||'window';const fit=clientSettings.fitMode||'fill';const zoom=Math.round(Number(clientSettings.zoom)||100);return `<div class="hub-section"><div class="hub-label">VISTA DEL CLIENTE</div><div class="hub-meta-card"><div class="hub-meta-row"><span>Modo</span><strong>${esc(fit)}</strong></div><div class="hub-row" style="margin-top:10px"><button class="hub-btn ${fit==='fill'?'primary':''}" data-fit="fill">Rellenar</button><button class="hub-btn ${fit==='contain'?'primary':''}" data-fit="contain">Ajustar</button><button class="hub-btn ${fit==='original'?'primary':''}" data-fit="original">Original</button><select id="clientZoomSelect" class="hub-select"><option value="90" ${zoom===90?'selected':''}>90%</option><option value="100" ${zoom===100?'selected':''}>100%</option><option value="110" ${zoom===110?'selected':''}>110%</option><option value="120" ${zoom===120?'selected':''}>120%</option></select></div></div></div><div class="hub-section"><div class="hub-label">CÓMO ABRIR EL HUB</div><div class="hub-open-modes"><button class="hub-btn ${mode==='overlay'?'primary':''}" data-open-mode="overlay"><strong>▣ Dentro del juego</strong><span>Panel integrado.</span></button><button class="hub-btn ${mode==='window'?'primary':''}" data-open-mode="window"><strong>▢ Ventana aparte</strong><span>Ventana independiente.</span></button><button class="hub-btn ${mode==='window-top'?'primary':''}" data-open-mode="window-top"><strong>◈ Siempre encima</strong><span>Ventana sobre el juego.</span></button></div></div><div class="hub-section"><div class="hub-label">PRIVACIDAD</div><div class="hub-check"><div><strong>Modo streamer / privado</strong><span>Oculta el nombre del perfil.</span></div><input id="streamerMode" type="checkbox" ${data.streamerMode?'checked':''}></div></div><div class="hub-section"><div class="hub-label">POSICIÓN DEL HUB</div><div class="hub-dock"><button class="hub-btn ${data.dock==='left'?'primary':''}" data-action="dock-left">← Izquierda</button><button class="hub-btn ${data.dock!=='left'?'primary':''}" data-action="dock-right">Derecha →</button></div></div>`;}
  function render(){stopHkCapture();stopAcCapture();if(!data||!content)return;renderTabs();const views={home:renderHome,smartbar:renderSmartbar,autoclick:renderAutoclick,alerts:renderAlerts,games:renderGames,assist:renderAssist,tools:renderTools,performance:renderPerformance,appearance:renderAppearance};content.innerHTML=views[tab]?views[tab]():renderHome();bind();applyTheme();updatePerfBadge();}

  let assistState={mode:'off',sequence:[]};
  function bind(){
    bindAutoclick();
    bindAlerts();
    const copyBtn=q('#copySettings');if(copyBtn)copyBtn.onclick=async()=>{const to=[...root.querySelectorAll('[data-copy-to]')].filter(x=>x.checked).map(x=>x.dataset.copyTo);const parts={bar:!!q('#copyBar')?.checked,calib:!!q('#copyCalib')?.checked};if(!to.length)return toast('Marca al menos un perfil.');if(!parts.bar&&!parts.calib)return toast('Elige qué copiar.');try{const r=await ipcRenderer.invoke('client:copy-settings',profileId,to,parts);toast(r&&r.ok?`Copiado a ${r.copied} perfil${r.copied===1?'':'es'}.`:(r&&r.message)||'No se pudo copiar.');}catch(_){toast('No se pudo copiar.');}};
    root.querySelectorAll('[data-sb-move]').forEach(el=>el.onclick=()=>{const [i,d]=el.dataset.sbMove.split(':').map(Number);const a=sbItems();const j=i+d;if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];sbSave(a);});
    root.querySelectorAll('[data-sb-del]').forEach(el=>el.onclick=()=>{sbEdit=null;sbSave(sbItems().filter(i=>i.id!==el.dataset.sbDel));});
    root.querySelectorAll('[data-sb-edit]').forEach(el=>el.onclick=()=>{sbEdit=el.dataset.sbEdit;render();});
    root.querySelectorAll('[data-sb-test]').forEach(el=>el.onclick=async()=>{const it=sbItems().find(i=>i.id===el.dataset.sbTest);if(!it)return;if(standalone())await clientAction('focus-game');const r=await clientAction('chat-shortcut',{text:it.text});toast(r===false?'No se pudo enviar.':'Enviado.');});
    const sbAddText=q('#sbAddText');if(sbAddText)sbAddText.onclick=()=>{sbEdit='new';render();};
    const sbCancel=q('#sbCancel');if(sbCancel)sbCancel.onclick=()=>{sbEdit=null;render();};
    const sbSaveItem=q('#sbSaveItem');if(sbSaveItem)sbSaveItem.onclick=()=>{
      const label=(q('#sbLabel')?.value||'').trim(),text=(q('#sbText')?.value||'').trim();
      if(!text)return toast('Escribe el mensaje del botón.');
      const items=sbItems();
      if(sbEdit==='new'){if(items.length>=SB_MAX)return toast('La barra ya está llena.');items.push({id:'t'+Date.now().toString(36),type:'text',label:label||text.slice(0,6),text});}
      else{const i=items.findIndex(x=>x.id===sbEdit);if(i<0)return;items[i]={...items[i],label:label||text.slice(0,6),text};}
      sbEdit=null;sbSave(items).then(()=>toast('Botón guardado.'));
    };
    const sbAddUpper=q('#sbAddUpper');if(sbAddUpper)sbAddUpper.onclick=()=>{const c=q('#sbColorSel')?.value;const items=sbItems();if(!c||!sbColor(c)||items.length>=SB_MAX)return;items.push({id:c,type:'upper',color:c});sbSave(items).then(()=>toast('Color añadido. Calibra su botón para usarlo.'));};
    const sbReset=q('#sbResetItems');if(sbReset)sbReset.onclick=()=>{sbEdit=null;setClientSetting('smartBarItems',null).then(()=>toast('Barra restablecida.'));};
    root.querySelectorAll('[data-hk]').forEach(el=>el.onclick=()=>startHkCapture(el.dataset.hk,el));
    root.querySelectorAll('[data-hk-clear]').forEach(el=>el.onclick=()=>{stopHkCapture();setClientSetting('hotkeys',{...(clientSettings.hotkeys||{}),...hkNow(),[el.dataset.hkClear]:''}).then(()=>toast('Atajo quitado.'));});
    const hkReset=q('#hkReset');if(hkReset)hkReset.onclick=()=>{stopHkCapture();setClientSetting('hotkeys',null).then(()=>toast('Atajos restablecidos.'));};
    root.querySelectorAll('[data-sb-learn]').forEach(el=>el.onclick=async()=>{const v=el.dataset.sbLearn;const payload=v==='all'?{mode:'all'}:v==='plus'?{mode:'plus'}:v==='reset'?{mode:'reset'}:{mode:'color',color:v.split(':')[1]};if(standalone())await clientAction('focus-game');await clientAction('smartbar-learn',payload);toast(v==='reset'?'Calibración borrada.':'Sigue las instrucciones dentro del juego.');if(!standalone()&&v!=='reset')toggle(false);});
    root.querySelectorAll('[data-sb-upper]').forEach(el=>el.onclick=async()=>{if(standalone())await clientAction('focus-game');await clientAction('smartbar-upper',{color:el.dataset.sbUpper});});
    const savePing=q('#savePingHost');if(savePing)savePing.onclick=async()=>{const host=q('#pingHost')?.value.trim()||'144.217.195.55';if(!/^[A-Za-z0-9][A-Za-z0-9.-]{0,251}$/.test(host))return toast('Dirección no válida.');await setClientSetting('pingHost',host);toast('Ping guardado.');};
    root.querySelectorAll('[data-action]').forEach(el=>el.onclick=async()=>doAction(el.dataset.action));
    root.querySelectorAll('[data-open-mode]').forEach(el=>el.onclick=async()=>{await save({openMode:el.dataset.openMode});toast(`Modo cambiado a ${el.dataset.openMode==='overlay'?'dentro del juego':el.dataset.openMode==='window-top'?'ventana + siempre encima':'ventana aparte'}`);});
    root.querySelectorAll('[data-client-setting]').forEach(el=>el.onchange=()=>setClientSetting(el.dataset.clientSetting,el.checked));root.querySelectorAll('[data-fit]').forEach(el=>el.onclick=()=>setClientSetting('fitMode',el.dataset.fit));const zoomSel=q('#clientZoomSelect');if(zoomSel)zoomSel.onchange=()=>setClientSetting('zoom',Number(zoomSel.value));
    root.querySelectorAll('[data-marker]').forEach(el=>el.onclick=async()=>{const a=el.dataset.marker;await clientAction('game-assist',{action:a});if(a==='marker-open'){if(standalone())await clientAction('focus-game');else toggle(false);}toast(a==='marker-open'?'Screen Marker abierto en el juego.':a==='marker-clear'?'Dibujo borrado.':'Screen Marker cerrado.');});
    root.querySelectorAll('[data-assist-mode]').forEach(el=>el.onclick=async()=>{assistState.mode=el.dataset.assistMode;await clientAction('game-assist',{action:'mode',mode:assistState.mode,gameId:currentGame.id});render();});
    root.querySelectorAll('[data-pen-color]').forEach(el=>el.onclick=()=>clientAction('game-assist',{action:'pen-color',color:el.dataset.penColor,gameId:currentGame.id}));
    const penSize=q('#penSizeSelect'); if(penSize) penSize.onchange=()=>clientAction('game-assist',{action:'pen-size',size:Number(penSize.value),gameId:currentGame.id});
    root.querySelectorAll('[data-assist-action]').forEach(el=>el.onclick=async()=>{const a=el.dataset.assistAction;if(a==='clear'||a==='reset'){assistState.mode='off';await clientAction('game-assist',{action:a==='clear'?'clear':'reset',gameId:currentGame.id});render();}else if(a==='sequence-clear'){assistState.sequence=[];render();}else if(a==='undo'){await clientAction('game-assist',{action:'undo',gameId:currentGame.id});render();}else if(a==='pen-undo'){await clientAction('game-assist',{action:'pen-undo',gameId:currentGame.id});}else if(a==='pen-clear'){await clientAction('game-assist',{action:'pen-clear',gameId:currentGame.id});}else if(a==='pen-off'){assistState.mode='off';await clientAction('game-assist',{action:'pen',active:false,gameId:currentGame.id});render();}else if(a==='timer-hide'){await clientAction('game-assist',{action:'hide-timer',gameId:currentGame.id});}});
    root.querySelectorAll('[data-assist-timer]').forEach(el=>el.onclick=()=>clientAction('game-assist',{action:'timer',seconds:Number(el.dataset.assistTimer),gameId:currentGame.id}));
    root.querySelectorAll('[data-perf-profile]').forEach(el=>el.onclick=()=>applyPerformanceProfile(el.dataset.perfProfile));
    root.querySelectorAll('[data-seq]').forEach(el=>el.onclick=()=>{assistState.sequence.push(el.dataset.seq);if(assistState.sequence.length>20)assistState.sequence.shift();const out=q('#sequenceText');if(out)out.textContent=`Secuencia: ${assistState.sequence.join(' · ')}`;});
    root.querySelectorAll('[data-action^="select-game:"]').forEach(el=>el.onclick=async()=>{const id=el.dataset.action.split(':')[1];currentGame={id,label:gameCatalog.find(g=>g.id===id)?.label||'Juego',confidence:1};await clientAction('game-assist',{action:'reset',gameId:id});tab='assist';render();});
    const cc=q('#hubClearCache');if(cc)cc.onclick=async()=>{cc.disabled=true;cc.textContent='Borrando…';const r=await clientAction('clear-cache');cc.disabled=false;cc.textContent='🧹 Borrar caché';toast(r&&r.ok?(r.freedMB>0?`Caché borrada (${r.freedMB} MB). Recargando el juego…`:'Caché borrada. Recargando el juego…'):'No se pudo borrar la caché.');};
    const sm=q('#streamerMode');if(sm)sm.onchange=()=>save({streamerMode:sm.checked});
  }
  async function setClientSetting(key,value){const next=await clientAction('set-settings',{[key]:value});if(next){clientSettings={...clientSettings,...next};applyTheme();render();}}
  async function applyPerformanceProfile(profile){if(profile==='performance'){await setClientSetting('performanceMode',true);await setClientSetting('showPerformance',true);toast('Modo rendimiento activado.');}else if(profile==='balanced-lite'){await setClientSetting('performanceMode',false);toast('Modo ahorro activado.');}else{await setClientSetting('performanceMode',false);toast('Modo equilibrado.');}}
  async function doAction(action){if(action?.startsWith('fav:')){const f=(data.favorites||[]).find(x=>x.id===action.slice(4));if(f)return doAction(f.action);return;}if(action?.startsWith('select-game:')){const id=action.split(':')[1];currentGame={id,label:gameCatalog.find(g=>g.id===id)?.label||'Juego',confidence:1};await clientAction('game-assist',{action:'reset',gameId:id});tab='assist';render();return;}if(action==='open-panel'||action==='open-hub'){await clientAction('open-hub');return;}if(action==='fullscreen'){const r=await clientAction('fullscreen');toast(r?'Pantalla completa activada.':'Pantalla completa desactivada.');return;}if(action==='reload'){await clientAction('reload');toast('Cliente recargado.');return;}if(action==='focus-game'){await clientAction('focus-game');return;}if(action==='show-launcher'){await clientAction('show-launcher');return;}if(action==='close-hub'){closeHub();return;}if(action==='toggle-performance'){await setClientSetting('showPerformance',!clientSettings.showPerformance);return;}if(action==='home'){tab='home';render();return;}if(action==='assist'){tab='assist';await detectGame();render();return;}if(action==='games'){tab='games';await detectGame();render();return;}if(action==='performance'){tab='performance';render();return;}if(action==='tools'){tab='tools';render();return;}if(action==='shortcuts'){tab='shortcuts';render();return;}if(action==='ringmode'){tab='ringmode';render();return;}if(action==='dock-left'){await save({dock:'left'});return;}if(action==='dock-right'){await save({dock:'right'});return;}const r=await quickAction(action);toast(r?.message||(r?.ok?'Listo.':'No se pudo ejecutar.'));}
  function updatePerfBadge(){const el=root?.querySelector('.hub-perf');if(!el)return;const on=Boolean(clientSettings?.showPerformance&&!clientSettings?.cleanMode);el.classList.toggle('on',on);if(on)el.textContent=`FPS ${fpsText()} · ${heapText()}`;}
  function tick(){if(!open)return;const clock=q('#hubSessionClock');if(clock)clock.textContent=fmtClock(currentSessionSeconds());updatePerfBadge();if(tab==='home'||tab==='performance')render();if(tab==='smartbar'&&standalone())refreshUpperStatus();}
  async function refreshUpperStatus(){try{const fresh=await ipcRenderer.invoke('client:panel-action',profileId,'get-settings');if(fresh&&JSON.stringify(fresh.upperColors||null)!==JSON.stringify(clientSettings.upperColors||null)){clientSettings={...clientSettings,...fresh};render();}}catch(_){}}
  function build(){const css=document.createElement('style');css.textContent=window.__BB_HUB_CSS__||'';document.documentElement.appendChild(css);const button=standalone()?null:(document.getElementById('__bb_hub_button')||(()=>{const b=document.createElement('button');b.id='__bb_hub_button';b.textContent='✦';b.title='Abrir BB Hub';b.setAttribute('aria-label','Abrir BB Hub');document.body.appendChild(b);return b;})());root=document.createElement('div');root.id='__bb_hub_root';root.innerHTML=`<div id="__bb_hub_backdrop"></div><div id="__bb_hub_window"><aside class="hub-side"><div class="hub-brand"><div class="hub-logo">BB</div><div><strong>BB Hub</strong><span>${standalone()?'Ventana independiente':'Client center'}</span></div></div><nav class="hub-side-nav" id="hubTabs"></nav><div class="hub-side-footer"><button class="hub-mini-btn" data-action="tools">⚙ Cliente</button><button class="hub-mini-btn" data-action="show-launcher">⌂ Launcher</button></div></aside><section class="hub-main"><header class="hub-header"><div class="hub-heading"><div class="hub-kicker">BOOMBANG CLIENT</div><div class="hub-title">Centro de juego</div><div class="hub-header-sub">Herramientas, cliente y accesos rápidos</div><div class="hub-profile" id="hubProfile">${esc(profileLabel)}</div></div><div class="hub-header-tools"><div class="hub-status" id="hubStatus"><i></i><span>Conectando…</span></div><button class="hub-close" id="hubClose">×</button></div></header><main class="hub-content" id="hubContent"></main></section><div class="hub-toast">Listo.</div><div class="hub-perf">FPS --</div></div>`;document.body.appendChild(root);tabs=q('#hubTabs');content=q('#hubContent');if(button)button.onclick=()=>clientAction('open-hub');q('#hubClose').onclick=()=>closeHub();q('#__bb_hub_backdrop').onclick=()=>toggle(false);document.addEventListener('__bb_launcher_command',e=>{if(standalone())return;if(e.detail?.type==='hub'&&e.detail.action==='open'){if(e.detail.tab)tab=e.detail.tab;toggle(true);}});getData().then(()=>{open=standalone()?true:open;render();});clearInterval(refreshTimer);refreshTimer=setInterval(()=>{if(open)tick();},1000);}
  function toggle(force){open=typeof force==='boolean'?force:!open;applyTheme();if(open){render();}}
  window.__BB_HUB_OPEN_TAB__ = requestedTab => { if(requestedTab) tab=String(requestedTab); open=true; render(); };
  function init(){if(!standalone()&&document.getElementById('__bb_hub_root'))return;build();}
  init();
})();
